import React from 'react';
import { motion } from 'framer-motion';
import { BriefcaseIcon, ArrowUpRight } from 'lucide-react';

const Experience = () => {
  const experiences = [
    {
      title: "Research Member",
      company: "RespAI Lab",
      period: "June 2024 - Present",
      description: "Pursuing research in Machine Unlearning and Copyright Protection for Diffusion Models, focusing on Responsible AI implementation.",
      skills: ["Machine Learning", "Diffusion Models", "Computer Vision"],
      link:"https://respailab.github.io",
      type: "Research"
    },
    {
      title: "Technical Executive: AI/ML",
      company: "Microsoft Learn Student Ambassadors",
      period: "Jan 2024 - Present",
      description: [
        "Developed and led an open-source framework for fine-tuning Stable Diffusion using LoRA, scaling to 10+ active contributors",
        "Engineered Wear-AI-ble, a generative AI application leveraging Stable Diffusion for custom T-shirt design generation",
        "Implemented DDQN reinforcement learning framework for Super Mario with custom reward shaping",
        "Demonstrated live MITM attack at D3FCON cybersecurity event to 400+ audience"
      ],
      skills: ["PyTorch", "Stable Diffusion", "Reinforcement Learning", "Leadership"],
      link: "https://mlsakiit.com",
      type: "Technical Leadership"
    }
  ];

  return (
    <section id="experience" className="relative py-32">
      {/* Decorative gradient */}
      <div className="absolute inset-0 bg-gradient-to-b from-background via-background/95 to-background" />
      
      <div className="section-container relative">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-20"
        >
          <h2 className="heading-2 mb-6">Experience</h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            My journey in machine learning research and technical leadership.
          </p>
        </motion.div>

        {/* Timeline */}
        <div className="max-w-4xl mx-auto">
          {experiences.map((experience, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true, margin: "-100px" }}
              transition={{ duration: 0.6, delay: index * 0.2 }}
              className="relative mb-16 last:mb-0"
            >
              {/* Timeline line */}
              {index !== experiences.length - 1 && (
                <div className="absolute left-8 top-16 bottom-0 w-px bg-gradient-to-b from-accent/50 to-transparent" />
              )}

              <div className="group relative grid md:grid-cols-[theme(spacing.16)_1fr] gap-8">
                {/* Timeline node */}
                <div className="relative">
                  <motion.div
                    initial={{ scale: 0 }}
                    whileInView={{ scale: 1 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.4, delay: index * 0.2 }}
                    className="w-16 h-16 rounded-2xl bg-accent/10 border border-accent/20 flex items-center justify-center"
                  >
                    <BriefcaseIcon className="w-8 h-8 text-accent" />
                  </motion.div>
                </div>

                {/* Content Card */}
                <div className="relative">
                  <motion.div
                    whileHover={{ y: -4 }}
                    className="relative p-8 rounded-2xl bg-background-light/50 backdrop-blur-sm border border-gray-800 hover:border-accent/50 transition-colors duration-300"
                  >
                    {/* Role Type Badge */}
                    <div className="absolute top-6 right-6 text-sm text-accent/90 bg-accent/10 px-4 py-1.5 rounded-full font-medium">
                      {experience.type}
                    </div>

                    {/* Content */}
                    <div className="space-y-6">
                      <div>
                        <h3 className="text-2xl font-semibold text-white group-hover:text-accent transition-colors">
                          {experience.title}
                        </h3>
                        <p className="text-lg text-gray-400 mt-1">{experience.company}</p>
                        <p className="text-accent mt-2">{experience.period}</p>
                      </div>

                      {/* Description */}
                      <div className="space-y-3">
                        {Array.isArray(experience.description) ? (
                          experience.description.map((item, i) => (
                            <p key={i} className="text-gray-400 text-lg">• {item}</p>
                          ))
                        ) : (
                          <p className="text-gray-400 text-lg">{experience.description}</p>
                        )}
                      </div>

                      {/* Skills */}
                      <div className="flex flex-wrap gap-2">
                        {experience.skills.map((skill, skillIndex) => (
                          <span
                            key={skillIndex}
                            className="text-sm text-gray-300 bg-background/60 px-4 py-1.5 rounded-full border border-gray-800"
                          >
                            {skill}
                          </span>
                        ))}
                      </div>

                     
                      {/* Learn More Link */}
                        {experience.link && (
                        <a 
                            href={experience.link}
                            target="_blank"
                            rel="noopener noreferrer"
                        >
                            <motion.div
                            whileHover={{ x: 4 }}
                            className="inline-flex items-center gap-2 text-accent cursor-pointer hover:text-accent/80 transition-colors"
                            >
                            Learn more <ArrowUpRight className="w-4 h-4" />
                            </motion.div>
                        </a>
                        )}
                    </div>
                  </motion.div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Experience;